4: 
5: pragma solidity ^0.8.20;
6: 
7: import {ECDSA} from "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
8: import {MessageHashUtils} from "@openzeppelin/contracts/utils/cryptography/MessageHashUtils.sol";
9: import {LibBytes} from "../../libraries/LibBytes.sol";
10: import {LibRedundantMath256} from "contracts/libraries/LibRedundantMath256.sol";
11: 
12: import {LibTractor} from "../../libraries/LibTractor.sol";
13: import {AdvancedFarmCall, LibFarm} from "../../libraries/LibFarm.sol";
14: import {LibBytes} from "contracts/libraries/LibBytes.sol";
15: /**
16:  * @title TractorFacet handles tractor and blueprint operations.
17:  * @author funderberker, 0xm00neth
18:  */
19: contract TractorFacet {
20:     using LibBytes for bytes32;
21:     using LibRedundantMath256 for uint256;
22: 
23:     event PublishRequisition(LibTractor.Requisition requisition);
24: 
25:     event CancelBlueprint(bytes32 blueprintHash);
26: 
27:     event Tractor(address indexed operator, bytes32 blueprintHash);
28: 
29:     /**
30:      * @notice Ensure requisition hash matches blueprint data and signer is publisher.
31:      */
32:     modifier verifyRequisition(LibTractor.Requisition calldata requisition) {
33:         bytes32 blueprintHash = LibTractor._getBlueprintHash(requisition.blueprint);
34:         require(blueprintHash == requisition.blueprintHash, "TractorFacet: invalid hash");
35:         address signer = ECDSA.recover(
36:             MessageHashUtils.toEthSignedMessageHash(requisition.blueprintHash),
37:             requisition.signature
38:         );
39:         require(signer == requisition.blueprint.publisher, "TractorFacet: signer mismatch");
40:         _;
41:     }
42: 
43:     /**
44:      * @notice Verify nonce and time are acceptable, increment nonce, set publisher, clear publisher.
45:      */
46:     modifier runBlueprint(LibTractor.Requisition calldata requisition) {
47:         require(
48:             LibTractor._getBlueprintNonce(requisition.blueprintHash) <
49:                 requisition.blueprint.maxNonce,
50:             "TractorFacet: maxNonce reached"
51:         );
52:         require(
53:             requisition.blueprint.startTime <= block.timestamp &&
54:                 block.timestamp <= requisition.blueprint.endTime,
55:             "TractorFacet: blueprint is not active"
56:         );
57:         LibTractor._incrementBlueprintNonce(requisition.blueprintHash);
58:         LibTractor._setPublisher(payable(requisition.blueprint.publisher));
59:         _;
60:         LibTractor._resetPublisher();
61:     }
62: 
63:     /**
64:      * @notice Publish a new blueprint by emitting its data in an event.
65:      */
66:     function publishRequisition(
67:         LibTractor.Requisition calldata requisition
68:     ) external verifyRequisition(requisition) {
69:         emit PublishRequisition(requisition);
70:     }
71: 
72:     /**
73:      * @notice Destroy existing blueprint
74:      */
75:     function cancelBlueprint(
76:         LibTractor.Requisition calldata requisition
77:     ) external verifyRequisition(requisition) {
78:         require(msg.sender == requisition.blueprint.publisher, "TractorFacet: not publisher");
79:         LibTractor._cancelBlueprint(requisition.blueprintHash);
80:         emit CancelBlueprint(requisition.blueprintHash);
81:     }
82: 
83:     /**
84:      * @notice Execute a Tractor blueprint as an operator.
85:      */
86:     function tractor(
87:         LibTractor.Requisition calldata requisition,
88:         bytes memory operatorData
89:     )
90:         external
91:         payable
92:         verifyRequisition(requisition)
93:         runBlueprint(requisition)
94:         returns (bytes[] memory results)
95:     {
96:         require(requisition.blueprint.data.length > 0, "Tractor: data empty");
97: 
98:         // Decode and execute advanced farm calls.
99:         // Cut out blueprint calldata selector.
100:         AdvancedFarmCall[] memory calls = abi.decode(
101:             LibBytes.sliceFrom(requisition.blueprint.data, 4),
102:             (AdvancedFarmCall[])
103:         );
104: 
105:         // Update data with operator-defined fillData.
106:         for (uint256 i; i < requisition.blueprint.operatorPasteInstrs.length; ++i) {
107:             bytes32 operatorPasteInstr = requisition.blueprint.operatorPasteInstrs[i];
108:             uint80 pasteCallIndex = operatorPasteInstr.getIndex1();
109:             require(calls.length > pasteCallIndex, "Tractor: pasteCallIndex OOB");
110: 
111:             LibBytes.pasteBytesTractor(
112:                 operatorPasteInstr,
113:                 operatorData,
114:                 calls[pasteCallIndex].callData
115:             );
116:         }
117: 
118:         results = new bytes[](calls.length);
119:         for (uint256 i = 0; i < calls.length; ++i) {
120:             require(calls[i].callData.length != 0, "Tractor: empty AdvancedFarmCall");
121:             results[i] = LibFarm._advancedFarm(calls[i], results);
122:         }
123:         emit Tractor(msg.sender, requisition.blueprintHash);
124:     }
125: 
126:     /**
127:      * @notice Get current counter value.
128:      * @return count Counter value
129:      */
130:     function getCounter(bytes32 counterId) public view returns (uint256 count) {
131:         return
132:             LibTractor._tractorStorage().blueprintCounters[
133:                 LibTractor._tractorStorage().activePublisher
134:             ][counterId];
135:     }
136: 
137:     /**
138:      * @notice Update counter value.
139:      * @return count New value of counter
140:      */
141:     function updateCounter(
142:         bytes32 counterId,
143:         LibTractor.CounterUpdateType updateType,
144:         uint256 amount
145:     ) external returns (uint256 count) {
146:         uint256 newCount;
147:         if (updateType == LibTractor.CounterUpdateType.INCREASE) {
148:             newCount = getCounter(counterId).add(amount);
149:         } else if (updateType == LibTractor.CounterUpdateType.DECREASE) {
150:             newCount = getCounter(counterId).sub(amount);
151:         }
152:         LibTractor._tractorStorage().blueprintCounters[
153:             LibTractor._tractorStorage().activePublisher
154:         ][counterId] = newCount;
